import math

# Function to calculate the minimum perimeter for an area A, assuming a compact shape (square)
def perimeter_from_area(A):
    R = math.sqrt(A)
    # For a perfect square, Perimeter = 4 * R
    return 4 * R

# Test cases
test_areas = [4, 9, 16, 25]
results = {}
for A in test_areas:
    P = perimeter_from_area(A)
    k_factor = P / math.sqrt(A)
    results[A] = {'Perimeter': P, 'k_factor': k_factor}

print("Test results for compact shapes (Square approximation):")
for A, res in results.items():
    print(f"Area A={A}: P={res['Perimeter']:.2f}, k_factor={res['k_factor']:.2f}")
